import json
import sys
import numpy as np
from collections import Counter
from itertools import combinations

def entity_set(sample):
    return set((e['text'], e['type']) for e in sample.get('entities', []))

def relation_set(sample):
    return set((r['head'], r['tail'], r['type']) for r in sample.get('relations', []))

def jaccard(s1, s2):
    if not s1 and not s2:
        return 1.0
    if not s1 or not s2:
        return 0.0
    return len(s1 & s2) / len(s1 | s2)

def pairwise_jaccard(sets_list):
    if len(sets_list) < 2:
        return 1.0
    sims = [jaccard(s1, s2) for s1, s2 in combinations(sets_list, 2)]
    return np.mean(sims)

def voting_confidence(sets_list):
    all_items = []
    for s in sets_list:
        all_items.extend(s)
    if not all_items:
        return 1.0
    counter = Counter(all_items)
    n = len(sets_list)
    union = set(all_items)
    voted = set()
    for item, count in counter.items():
        if count > n / 2:
            voted.add(item)
    if not union:
        return 1.0
    confidences = []
    for item in union:
        confidences.append(counter[item] / n)
    return np.mean(confidences)

def f1_score(pred_set, gold_set):
    if not pred_set and not gold_set:
        return 1.0
    if not pred_set or not gold_set:
        return 0.0
    tp = len(pred_set & gold_set)
    p = tp / len(pred_set) if pred_set else 0
    r = tp / len(gold_set) if gold_set else 0
    if p + r == 0:
        return 0.0
    return 2 * p * r / (p + r)

def majority_vote(sets_list):
    all_items = []
    for s in sets_list:
        all_items.extend(s)
    counter = Counter(all_items)
    n = len(sets_list)
    return set(item for item, count in counter.items() if count > n / 2)

def process(samples_file, logprob_file, output_file):
    # Load both files keyed by id
    samples_data = {}
    with open(samples_file) as f:
        for line in f:
            d = json.loads(line)
            samples_data[d['id']] = d

    logprob_data = {}
    with open(logprob_file) as f:
        for line in f:
            d = json.loads(line)
            logprob_data[d['id']] = d

    results = []
    for doc_id, doc in samples_data.items():
        gold_ents = entity_set(doc['gold'])
        gold_rels = relation_set(doc['gold'])
        samples = doc['samples']

        ent_sets = [entity_set(s) for s in samples]
        rel_sets = [relation_set(s) for s in samples]

        # Soft Jaccard
        sj_ner = pairwise_jaccard(ent_sets)
        sj_re = pairwise_jaccard(rel_sets)

        # Voting confidence
        vc_ner = voting_confidence(ent_sets)
        vc_re = voting_confidence(rel_sets)

        # F1 of majority vote vs gold
        voted_ents = majority_vote(ent_sets)
        voted_rels = majority_vote(rel_sets)
        f1_ner = f1_score(voted_ents, gold_ents)
        f1_re = f1_score(voted_rels, gold_rels)

        # Mean sample F1 vs gold (alternative accuracy measure)
        sample_ner_f1s = [f1_score(es, gold_ents) for es in ent_sets]
        sample_re_f1s = [f1_score(rs, gold_rels) for rs in rel_sets]
        mean_sample_ner_f1 = np.mean(sample_ner_f1s)
        mean_sample_re_f1 = np.mean(sample_re_f1s)

        # Logprob (mean across samples)
        lp_doc = logprob_data.get(doc_id)
        if lp_doc:
            lp_samples = lp_doc['samples']
            mean_logprob = np.mean([s.get('mean_logprob', 0) for s in lp_samples])
        else:
            mean_logprob = None

        results.append({
            'id': doc_id,
            'sj_ner': sj_ner,
            'sj_re': sj_re,
            'vc_ner': vc_ner,
            'vc_re': vc_re,
            'f1_ner': f1_ner,
            'f1_re': f1_re,
            'mean_sample_ner_f1': mean_sample_ner_f1,
            'mean_sample_re_f1': mean_sample_re_f1,
            'mean_logprob': mean_logprob,
            'has_gold_ents': len(gold_ents) > 0,
            'has_gold_rels': len(gold_rels) > 0,
        })

    with open(output_file, 'w') as f:
        json.dump(results, f)
    print(f"Wrote {len(results)} instances to {output_file}")

process(
